from scipy.optimize import least_squares
E=df['eps'].values;TT=df['T'].values;S=df['sigma'].values
forms={
 'eps^p*exp(f T)': lambda p: E**p[0]*np.exp(p[1]*TT),
 'exp(-f/T)*eps^p': lambda p: E**p[0]*np.exp(-p[1]/TT),
 'exp(fT)*(1-exp(-q eps))': lambda p: (1-np.exp(-p[0]*E))*np.exp(p[1]*TT),
 'exp(f T + g T^2)': lambda p: np.exp(p[0]*TT+p[1]*TT**2),
 'T^p*exp(-q eps)': lambda p: TT**p[0]*np.exp(-p[1]*E),
 'exp(-q eps^2)*T^p': lambda p: TT**p[0]*np.exp(-p[1]*E**2),
}
for name,g in forms.items():
    best=None
    for c0 in [0.3,0.75,1.5]:
      for a0 in [-1,0.5,2]:
        def f(p):
            B=np.column_stack([np.ones_like(E),E*np.exp(-p[0]*E)/TT,g(p[1:])])
            w,*_=np.linalg.lstsq(B,S,rcond=None)
            return S-B@w
        try:
            r=least_squares(f,[c0,a0,0.5] if name not in ('exp(-f/T)*eps^p','exp(fT)*(1-exp(-q eps))','exp(f T + g T^2)','T^p*exp(-q eps)','exp(-q eps^2)*T^p') else [c0,a0])
            if best is None or r.cost<best.cost: best=r
        except Exception as ex: pass
    print(name, np.mean(best.fun**2)/np.var(S), best.x)

